#include "composition_intelligence/StrategicContextBridge.hpp"
#include <cassert>
#include <iostream>
#include <optional>
using namespace tft;
using namespace tft::composition_intelligence;
namespace {
strategy::StrategicSharedContext make_context(){strategy::StrategicSharedContext c;c.player_id=3;c.round=12;c.hp=64;c.gold=42;c.level=7;c.xp=4;c.xp_to_next=16;c.win_streak=3;c.board_power=58.5;c.relative_board_power=1.12;c.current_direction_score=.72;c.current_direction_viable=true;c.current_composition_direction="Shepherd";c.composition_locked=true;return c;}
strategy::StrategicPlanDecision make_plan(){strategy::StrategicPlanDecision p;p.composition_decision=strategy::CompositionDecision::Pivot;p.target_composition_direction="Invoker";p.confidence=.61;return p;}
strategy::EconomicControlDecision make_economy(){strategy::EconomicControlDecision e;e.posture=strategy::EconomicPosture::InvestExperience;e.confidence=.77;return e;}
ContextBridgeInput make_input(const strategy::StrategicSharedContext& c,const strategy::StrategicPlanDecision& p,const strategy::EconomicControlDecision& e,const std::optional<ActiveComposition>& a){ContextBridgeInput i;i.strategic=&c;i.strategic_decision=&p;i.economic_decision=&e;i.active_composition=&a;i.match_id=99;i.expected_player_id=3;i.expected_round=12;i.timestamp_unix_ms=123456;i.sequence=8;return i;}
void valid_mapping_preserves_observed_values(){auto c=make_context();auto p=make_plan();auto e=make_economy();std::optional<ActiveComposition>a{ActiveComposition{}};a->candidate.composition_id="native-18-shepherd";a->version=4;auto r=StrategicContextBridge::adapt(make_input(c,p,e,a));assert(r.metadata.quality==ContextBridgeQuality::Valid);assert(r.metadata.match_id==99&&r.metadata.player_id==3&&r.metadata.round==12&&r.metadata.sequence==8&&r.metadata.timestamp_unix_ms==123456);assert(r.metadata.composition_id=="native-18-shepherd"&&r.metadata.composition_version==4);assert(r.gold.value&&*r.gold.value==42&&r.gold.origin==ContextValueOrigin::Observed);assert(r.observed_direction.value&&*r.observed_direction.value=="Shepherd");assert(r.recommended_direction.value&&*r.recommended_direction.value=="Invoker"&&r.recommended_direction.origin==ContextValueOrigin::Recommended);assert(r.economic_posture.value&&*r.economic_posture.value=="INVEST_EXPERIENCE");}
void missing_active_is_partial(){auto c=make_context();auto p=make_plan();auto e=make_economy();std::optional<ActiveComposition>a;auto r=StrategicContextBridge::adapt(make_input(c,p,e,a));assert(r.metadata.quality==ContextBridgeQuality::Partial);assert(r.metadata.composition_id.empty()&&r.metadata.composition_version==0);assert(r.gold.value&&*r.gold.value==42);assert(r.recommended_direction.quality==ContextBridgeQuality::Partial);}
void player_mismatch_is_incompatible(){auto c=make_context();c.player_id=4;auto p=make_plan();auto e=make_economy();std::optional<ActiveComposition>a{ActiveComposition{}};auto r=StrategicContextBridge::adapt(make_input(c,p,e,a));assert(r.metadata.quality==ContextBridgeQuality::Incompatible);assert(r.metadata.reason=="player_id_mismatch"&&!r.gold.value&&!r.recommended_direction.value);}
void round_mismatch_is_stale(){auto c=make_context();c.round=11;auto p=make_plan();auto e=make_economy();std::optional<ActiveComposition>a{ActiveComposition{}};auto r=StrategicContextBridge::adapt(make_input(c,p,e,a));assert(r.metadata.quality==ContextBridgeQuality::Stale);assert(r.metadata.reason=="round_mismatch"&&!r.gold.value&&!r.economic_posture.value);}
void missing_sources_are_explicit(){auto r=StrategicContextBridge::adapt(ContextBridgeInput{});assert(r.metadata.quality==ContextBridgeQuality::Missing);assert(!r.gold.value);}
}
int main(){valid_mapping_preserves_observed_values();missing_active_is_partial();player_mismatch_is_incompatible();round_mismatch_is_stale();missing_sources_are_explicit();std::cout<<"Strategic context bridge tests passed\n";return 0;}
